const additionalData = target.additional_data || (target.additional_data = {});
let { importManager } = additionalData;

if (!importManager) {
	Promise.resolve(window.TDF?.bundles?.tdf || import('../jsBundles/tdf.es.js')).then(() => {
		importManager = additionalData.importManager =
			new window.TDF.import.managers.FileImportManager({
				aras: window.aras,
				configs: [],
			});

		window.layout.observer.notify('UpdateTearOffWindowState');

		const importTracker = new window.TDF.import.eventTrackers.ImportStatus(
			importManager,
			{ aras: window.aras, autoStart: true }
		);

		importTracker.addEventListener('importCanceled', () => {
			importManager.cancel();
		});
	});
}

return {
	disabled: !(
		window.isEditMode &&
		importManager?.hasConfigs()
	),
};
